import Foundation
import Testing

@testable import SwaTex

/// Coverage-targeted golden layout parity tests.
///
/// `Resources/golden/test_cases_coverage.jsonl` was generated by running the
/// RaTeX (Rust) reference engine (`target/release/ratex-layout`) over a corpus
/// of formulas chosen to exercise engine branches not covered by the main
/// golden corpora: stretchy x-arrows, CD diagrams, proof trees with labels,
/// stacked delimiters for every delimiter family, exotic `\ce`/`\pu` inputs,
/// unicode sub/superscripts, html style/class/data commands, sizing, spacing
/// commands, genfrac variants, and more. Metrics must match Rust exactly
/// (both engines round to 5 decimals). Entries with `"error": true` were
/// rejected by the Rust engine and must be rejected by SwaTex too.
///
/// EXCEPTIONS — do NOT blindly regenerate from RaTeX: five entries were
/// hand-edited to KaTeX-correct values where RaTeX shares the original bug
/// (unterminated `\verb`, `x\limits^2` — now errors; `\vcenter` depths —
/// now axis-centered ink). They are pinned by LayoutFixRegressionTests /
/// ParserSpecTests / HardeningTests; regeneration must preserve them (see
/// README "Known limitations").
@Suite("CoverageGolden")
struct CoverageGoldenTests {
    struct Fixture: Decodable {
        struct DL: Decodable {
            var width: Double
            var height: Double
            var depth: Double
            var itemCount: Int
        }
        var input: String
        var displayList: DL?
        var error: Bool?
    }

    private func round5(_ v: Double) -> Double {
        (v * 100000).rounded() / 100000
    }

    @Test func coverageCorpus() throws {
        let url = try #require(
            Bundle.module.url(
                forResource: "test_cases_coverage", withExtension: "jsonl",
                subdirectory: "golden"))
        let text = try String(contentsOf: url, encoding: .utf8)
        let decoder = JSONDecoder()
        let fixtures = try text.split(separator: "\n").map {
            try decoder.decode(Fixture.self, from: Data($0.utf8))
        }
        #expect(fixtures.count > 600)

        var mismatches: [String] = []
        for fixture in fixtures {
            let result = Result { () throws(ParseError) -> DisplayList in
                let ast = try parseLaTeX(fixture.input)
                return toDisplayList(layout(ast, options: LayoutOptions()))
            }
            switch (result, fixture.error == true) {
            case (.success(let dl), false):
                guard let fdl = fixture.displayList else {
                    mismatches.append("\(fixture.input): fixture missing displayList")
                    continue
                }
                if round5(dl.width) != fdl.width || round5(dl.height) != fdl.height
                    || round5(dl.depth) != fdl.depth || dl.items.count != fdl.itemCount
                {
                    mismatches.append(
                        "\(fixture.input): swift(w:\(round5(dl.width)) h:\(round5(dl.height)) "
                            + "d:\(round5(dl.depth)) n:\(dl.items.count)) "
                            + "rust(w:\(fdl.width) h:\(fdl.height) d:\(fdl.depth) n:\(fdl.itemCount))"
                    )
                }
            case (.failure, true):
                break  // both engines reject — OK
            case (.success, true):
                mismatches.append("\(fixture.input): Swift parsed but Rust errored")
            case (.failure(let e), false):
                mismatches.append("\(fixture.input): Swift errored (\(e)) but Rust parsed")
            }
        }

        let detail =
            "\(mismatches.count) mismatches:\n" + mismatches.prefix(20).joined(separator: "\n")
        #expect(mismatches.isEmpty, Comment(rawValue: detail))
    }
}
